def get_academic_integrity_rules_catalog() -> List[AcademicIntegrityRulesRecord]:
    """Return complete academic_integrity_rules registry."""
    return REGISTRY_ACADEMIC_INTEGRITY_RULES


def query_academic_integrity_rules_by_difficulty(difficulty_level: str) -> List[AcademicIntegrityRulesRecord]:
    """Filter academic_integrity_rules elements matching difficulty."""
    return [item for item in REGISTRY_ACADEMIC_INTEGRITY_RULES if item.difficulty == difficulty_level]


def calculate_academic_integrity_rules_total_weight() -> float:
    """Compute cumulative weighting of curriculum units."""
    return sum(item.weight for item in REGISTRY_ACADEMIC_INTEGRITY_RULES)

